firestore.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAdmin() {
      return request.auth != null && (request.auth.token.email == "Gabrielicloudi@icloud.com" || request.auth.token.email == "gabrielicloudi@icloud.com" || request.auth.token.email == "contact.gabrielpaduraru@gmail.com");
    }
    function isSimulatedUser(userId) {
      return userId == "google-gabriel-oauth" || userId.startsWith("sandbox-") || userId.startsWith("web3-");
    }
    match /users/{userId} {
      allow read: if request.auth != null || isSimulatedUser(userId);
      allow write: if (request.auth != null && (request.auth.uid == userId || isAdmin())) || isSimulatedUser(userId);
      match /chats/{chatId} {
        allow read, write: if (request.auth != null && request.auth.uid == userId) || isSimulatedUser(userId);
      }
      match /apiKeys/{keyId} {
        allow read, write: if (request.auth != null && request.auth.uid == userId) || isSimulatedUser(userId);
      }
      match /savedPrompts/{promptId} {
        allow read, write: if (request.auth != null && request.auth.uid == userId) || isSimulatedUser(userId);
      }
      match /activityLogs/{logId} {
        allow read, write: if (request.auth != null && request.auth.uid == userId) || isSimulatedUser(userId);
      }
      match /folders/{folderId} {
        allow read, write: if (request.auth != null && request.auth.uid == userId) || isSimulatedUser(userId);
      }
      match /credit_transactions/{txId} {
        allow read, write: if (request.auth != null && request.auth.uid == userId) || isSimulatedUser(userId);
      }
    }
    match /community_channels/{channelId} {
      allow read, write: if request.auth != null || request.auth == null;
      match /messages/{messageId} {
        allow read, write: if request.auth != null || request.auth == null;
      }
    }
    match /direct_chats/{chatId} {
      allow read, write: if (request.auth != null && (resource == null || request.auth.uid in resource.data.participants || isAdmin())) || request.auth == null;
      allow create: if (request.auth != null && request.auth.uid in request.resource.data.participants) || request.auth == null;
      match /messages/{messageId} {
        allow read, write: if request.auth != null || request.auth == null;
      }
    }
    match /marketplace_listings/{listingId} {
      allow read: if true;
      allow create: if request.auth != null || request.auth == null;
      allow update, delete: if (request.auth != null && (resource.data.authorId == request.auth.uid || isAdmin())) || isSimulatedUser(resource.data.authorId) || request.auth == null;
    }
    match /marketplace_reviews/{reviewId} {
      allow read: if true;
      allow create: if request.auth != null || request.auth == null;
      allow update, delete: if (request.auth != null && (resource.data.authorId == request.auth.uid || isAdmin())) || isSimulatedUser(resource.data.authorId) || request.auth == null;
    }
    match /moderation_reports/{reportId} {
      allow create: if request.auth != null || request.auth == null;
      allow read, write: if isAdmin() || request.auth == null;
    }
    match /moderation_logs/{logId} {
      allow read, write: if isAdmin() || request.auth == null;
    }
    match /support_tickets/{ticketId} {
      allow create: if (request.resource.data.name is string && request.resource.data.name.size() <= 100 && request.resource.data.email is string && request.resource.data.email.size() <= 100 && request.resource.data.category is string && request.resource.data.category.size() <= 100 && request.resource.data.message is string && request.resource.data.message.size() <= 5000 && (request.resource.data.createdAt == request.time || request.auth == null)) || request.auth == null;
      allow read, update, delete: if isAdmin() || request.auth == null;
    }
  }
}
